def find_not_equal(arr, queries):
    n = len(arr)
    results = []

    # Precompute next index where value changes
    next_diff = [0] * (n + 1)
    next_diff[n] = n + 1

    for i in range(n - 1, 0, -1):
        if arr[i] != arr[i - 1]:
            next_diff[i] = i + 1
        else:
            next_diff[i] = next_diff[i + 1]

    for l, r, x in queries:
        l -= 1  # Convert to 0-indexed
        r -= 1

        # If first element is different from x
        if arr[l] != x:
            results.append(l + 1)  # Convert back to 1-indexed
            continue

        # Find next index with a different value
        next_idx = next_diff[l + 1]

        # Check if it's within the range and value is different from x
        if next_idx <= r + 1 and (next_idx == n + 1 or arr[next_idx - 1] != x):
            results.append(next_idx)
        else:
            # Need to scan the range to find a position with value != x
            found = False
            for i in range(l, r + 1):
                if arr[i] != x:
                    results.append(i + 1)  # Convert back to 1-indexed
                    found = True
                    break

            if not found:
                results.append(-1)

    return results

