def solve(n):
    n_str = str(n)
    n_len = len(n_str)

    for half_len in range(1, (n_len + 1) // 2 + 1):
        for first_half in range(10**(half_len-1), 10**half_len):
            # For even length: try to find the second half directly
            if n_len % 2 == 0 and n_len == 2 * half_len:
                first_half_str = str(first_half)
                second_half_str = n_str[half_len:]

                a = int(first_half_str + second_half_str)
                ar = int(second_half_str[::-1] + first_half_str[::-1])

                if a + ar == n and str(ar)[0] != '0':
                    return a

            # Try to generate a candidate by filling in the middle part
            if n_len <= 2 * half_len:
                continue

            first_half_str = str(first_half)
            first_half_rev = first_half_str[::-1]

            remaining_len = n_len - 2 * half_len
            for middle in range(10**(remaining_len-1), 10**remaining_len):
                middle_str = str(middle)
                if len(middle_str) != remaining_len:
                    continue

                a = int(first_half_str + middle_str + first_half_rev)
                ar = int(first_half_str[::-1] + middle_str[::-1] + first_half_rev[::-1])

                if a + ar == n and str(ar)[0] != '0':
                    return a

    # Try general candidates
    for d in range(1, 100):
        for j in range(1, 100):
