def solve(n):
    # Convert n to int if it's small enough, otherwise keep as string
    try:
        n = int(n)
    except:
        pass

    # If n is small, handle directly
    if isinstance(n, int) and n <= 9:
        return str(n) + str(n)

    # For n > 9, we need to find the corresponding palindrome
    if isinstance(n, int) and n == 10:
        return "1001"

    # For any n, we can determine the palindrome without generating all of them
    # The first 9 palindromes are single-digit repeated: 11, 22, ..., 99
    # After that, we have palindromes like 1001, 1111, ..., 9999, 10001, ...

    # Convert n to int if it's still a string
    if isinstance(n, str):
        n = int(n)

    # Handle special case for n <= 9
    if n <= 9:
        return str(n) + str(n)

    # For n > 9, find the corresponding number
    n -= 9  # Adjust for the first 9 palindromes

    # Find the left half of the palindrome
    left_half = str(n + 9)  # +9 because we start from 10 after the first 9 palindromes

    # Create the palindrome by mirroring the left half
    return left_half + left_half[::-1]

