def nth_even_length_palindrome(n):
    n_str = str(n)

    # If n has only 1 digit
    if len(n_str) == 1:
        if int(n_str) <= 9:
            return int(n_str) * 10 + int(n_str)

    # If n is a power of 10, it's a special case
    if n_str == '1' + '0' * (len(n_str) - 1):
        half = '1' + '0' * (len(n_str) - 1)
        return int(half + half[::-1])

    # Regular case: construct a palindrome with n as the first half
    half_length = (len(n_str) + 1) // 2
    first_half = n_str[:half_length]

    # For odd length n, we exclude the middle digit when reflecting
    if len(n_str) % 2 == 1:
        return int(first_half + first_half[:-1][::-1])
    else:
        return int(first_half + first_half[::-1])

