def min_seconds_to_transform(x, y):
    dp = {}

    def get_min_seconds(a, b, c, target):
        if a == target and b == target and c == target:
            return 0

        state = tuple(sorted([a, b, c]))
        if state in dp:
            return dp[state]

        result = float('inf')
        for i in range(3):
            sides = [a, b, c]
            current = sides[i]
            sides.pop(i)

            # Try decreasing the side
            for new_value in range(max(1, current - 1), current):
                if new_value > sum(sides) - max(sides) and new_value < sum(sides):
                    if i == 0:
                        result = min(result, 1 + get_min_seconds(new_value, b, c, target))
                    elif i == 1:
                        result = min(result, 1 + get_min_seconds(a, new_value, c, target))
                    else:
                        result = min(result, 1 + get_min_seconds(a, b, new_value, target))

        dp[state] = result
        return result

    return get_min_seconds(x, x, x, y)

