def jumping_ball(n, bumpers):
    visited = [False] * (n + 1)
    will_fall = [False] * (n + 1)

    for pos in range(1, n + 1):
        if visited[pos]:
            continue

        # Track path of the ball
        path = []
        curr_pos = pos
        cycle_detected = False

        while 1 <= curr_pos <= n and not visited[curr_pos]:
            visited[curr_pos] = True
            path.append(curr_pos)

            # Determine next position
            if bumpers[curr_pos - 1] == '>':
                curr_pos += 1
            else:  # '<'
                curr_pos -= 1

        # Check if ball falls or gets into previously visited position
        if curr_pos < 1 or curr_pos > n:
            # Ball falls
            for p in path:
                will_fall[p] = True
        elif curr_pos in path:
            # Ball enters a cycle
            cycle_start = path.index(curr_pos)
            # Mark positions before the cycle as ones that will fall
            for p in path[:cycle_start]:
                will_fall[p] = True
        else:
            # Ball reaches a position already known to fall or stay
            if will_fall[curr_pos]:
                for p in path:
                    will_fall[p] = True

    return sum(will_fall[1:])

