def solve_servers_problem(n, q, tasks):
    servers_busy_until = [0] * (n + 1)  # servers are 1-indexed
    results = []

    for t, k, d in tasks:
        # Find available servers at time t
        available_servers = []
        for i in range(1, n + 1):
            if servers_busy_until[i] <= t:
                available_servers.append(i)
                if len(available_servers) == k:
