def min_clicks(n, variants):
    total_clicks = 0
    for i in range(n):
        if i == 0:
            total_clicks += variants[i]
        else:
            # For each question other than the first one, we might need to restart
            # from the beginning multiple times in the worst case
            total_clicks += variants[i] * (sum(variants[:i]) + 1)
    return total_clicks

