def calculate_probability(n, m, h, s):
    total_students = sum(s)
    total_students_without_wafa = total_students - 1  # Subtract Herr Wafa

    # Check if there are enough students to form a team
    if total_students_without_wafa < n - 1:
        return -1

    # Number of students in Herr Wafa's department (excluding Herr Wafa)
    h_students = s[h - 1] - 1

    # If there are no other students in Herr Wafa's department
    if h_students == 0:
        return 0.0

    # Calculate the probability of selecting at least one student from Herr Wafa's department
    probability = 1.0 - (
        # Ways to choose n-1 students, all from departments other than Herr Wafa's
        choose(total_students_without_wafa - h_students, n - 1) / 
        # Total ways to choose n-1 students from all departments (excluding Herr Wafa)
        choose(total_students_without_wafa, n - 1)
    )

    return probability

def choose(n, k):
    """Compute C(n,k), the number of ways to choose k items from n items"""
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1

    result = 1
    for i in range(1, k + 1):
        result = result * (n - (i - 1)) // i

    return result

def main():
    n, m, h = map(int, input().split())
    s = list(map(int, input().split()))

    result = calculate_probability(n, m, h, s)
    if result == -1:
        print(-1)
    else:
        print(result)

