        i += 6
    return True

def find_prime_factors(n):
    factors = []
    # Check for 2 as a factor
    while n % 2 == 0:
        factors.append(2)
        n //= 2

    # Check for other prime factors
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 2

    # If n is a prime number greater than 2
    if n > 2:
        factors.append(n)

    return factors

