        return 1

    result = n
    current = n

    while current > 1:
        # Find all divisors of current
        divisors = []
        i = 1
        while i * i <= current:
            if current % i == 0:
                divisors.append(i)
                if i != current // i:
                    divisors.append(current // i)
            i += 1

        # Sort divisors to find the largest proper divisor (less than current)
        divisors.sort()
        for j in range(len(divisors) - 2, -1, -1):
            if divisors[j] < current:
                current = divisors[j]
                break

        result += current

    return result

