    # Convert string to list for easier manipulation
    queue = list(s)

    # Simulate t seconds
    for _ in range(t):
        i = 0
        # Process queue for one second
        while i < n - 1:
            if queue[i] == 'B' and queue[i + 1] == 'G':
                # Swap boy and girl
                queue[i], queue[i + 1] = queue[i + 1], queue[i]
                i += 2  # Skip the next position as it's already processed
            else:
                i += 1

