def king_path(start, end):
    # Convert chess notation to coordinates
    start_x, start_y = ord(start[0]) - ord('a'), int(start[1]) - 1
    end_x, end_y = ord(end[0]) - ord('a'), int(end[1]) - 1

    # Directions: L, R, U, D, LU, LD, RU, RD
    directions = {
        "L": (-1, 0), "R": (1, 0), "U": (0, 1), "D": (0, -1),
        "LU": (-1, 1), "LD": (-1, -1), "RU": (1, 1), "RD": (1, -1)
    }

    moves = []

    while start_x != end_x or start_y != end_y:
        dx = end_x - start_x
        dy = end_y - start_y

        move_direction = ""

        if dx < 0:
            move_direction += "L"
        elif dx > 0:
            move_direction += "R"

        if dy > 0:
            move_direction += "U"
        elif dy < 0:
            move_direction += "D"

        dx_move, dy_move = directions[move_direction]
        start_x += dx_move
        start_y += dy_move

        moves.append(move_direction)

    return moves

