                if a[idx] < i - j:
                    substring_valid = False
                    break

            if substring_valid:
                dp[i] = (dp[i] + dp[j]) % MOD

    # Calculate max substring length
    max_length = 0
    for length in range(n, 0, -1):
        for i in range(length, n + 1):
            j = i - length

            # Check if s[j:i] can be valid
            substring_valid = True
            char_count = {}

            for k in range(j, i):
