    needed_zeros = k
    zeros_found = 0
    digits_to_keep = 0

    # Start from the end
    for i in range(len(s) - 1, -1, -1):
        if s[i] == '0':
            zeros_found += 1
            if zeros_found <= needed_zeros:
                digits_to_keep += 1
        else:
            # If we have all needed zeros, we can break
            if zeros_found >= needed_zeros:
                break
            digits_to_keep += 1

    # If we can't find enough zeros, the only option is to return 0
    if zeros_found < needed_zeros:
        return len(s) - 1

    return len(s) - digits_to_keep

