    cum_sum = [0] * n
    for i in range(1, n):
        cum_sum[i] = cum_sum[i-1] + abs(a[i] - a[i-1])

    for l in range(n-1):
        for r in range(l+1, n):
            # Calculate f(l, r) = |a[l] - a[r]| + sum of adjacent differences in range [l, r-1]
            adjacent_diff_sum = cum_sum[r] - cum_sum[l]
            f_value = abs(a[l] - a[r]) + adjacent_diff_sum

