def analyze_distribution(numbers, population):
    # Check if all numbers are within expected range [-(population-1), population]
    for num in numbers:
        if num < -(population-1) or num > population:
            return "poisson"

    # Count occurrences of each number
    occurrences = {}
    for num in numbers:
        occurrences[num] = occurrences.get(num, 0) + 1

    # For uniform distribution, we expect all numbers in the range to have roughly the same frequency
    unique_nums = len(occurrences)
    expected_range = 2 * population  # Range is from -(population-1) to population, which is 2*population numbers

    # If we have significantly fewer unique numbers than expected in uniform distribution or if frequencies vary too much
    if unique_nums <= expected_range * 0.7:
        return "poisson"

    # Calculate the mean and variance
    mean = sum(numbers) / len(numbers)
    variance = sum((x - mean) ** 2 for x in numbers) / len(numbers)

    # For Poisson, mean ≈ variance; for uniform, variance = (b-a)²/12 where b-a is the range
