            total_cost = min_cost_by_duration[duration1] + min_cost_by_duration[x - duration1]
            min_total_cost = min(min_total_cost, total_cost)

    # If we need two vouchers with the same duration, check if we have at least two with this duration
    if x % 2 == 0 and x // 2 in min_cost_by_duration:
        # Need to find the two cheapest vouchers with duration x // 2
