    positions = {
        '^': {'cw': '>', 'ccw': '<'},
        '>': {'cw': 'v', 'ccw': '^'},
        'v': {'cw': '<', 'ccw': '>'},
        '<': {'cw': '^', 'ccw': 'v'}
    }

