    n = n % 4  # Since positions repeat every 4 steps

    # Check if clockwise rotation matches the end position
    cw_pos = start
    for _ in range(n):
        cw_pos = positions[cw_pos]['cw']

    # Check if counter-clockwise rotation matches the end position
    ccw_pos = start
    for _ in range(n):
        ccw_pos = positions[ccw_pos]['ccw']

    # Determine the direction
    if cw_pos == end and ccw_pos != end:
        return "cw"
    elif ccw_pos == end and cw_pos != end:
        return "ccw"
    else:
        return "undefined"

