def spinner_problem(start, end, n):
    positions = "^>v<"
    start_idx = positions.find(start)
    end_idx = positions.find(end)

    # Calculate possible final positions for both directions
    clockwise_idx = (start_idx + n) % 4
    counterclockwise_idx = (start_idx - n) % 4

    if clockwise_idx == end_idx and counterclockwise_idx == end_idx:
        return "undefined"
    elif clockwise_idx == end_idx:
        return "cw"
    elif counterclockwise_idx == end_idx:
        return "ccw"
    else:
        return "undefined"

