def count_arrangements(n, m):
    MOD = 10**9 + 7

    # dp[i][j][k] = number of ways to have i people boarded, 
    # with j people from front, k people from back
    dp = [[[0 for _ in range(m + 1)] for _ in range(m + 1)] for _ in range(m + 1)]
    dp[0][0][0] = 1

    for i in range(1, m + 1):
        for j in range(i + 1):
            for k in range(i - j + 1):
                if j + k != i:
                    continue

                # Add a person from the front
                if j > 0:
                    # Assign any seat from 1 to (n - k)
                    dp[i][j][k] = (dp[i][j][k] + dp[i-1][j-1][k] * max(0, n - k)) % MOD

                # Add a person from the back
                if k > 0:
                    # Assign any seat from (j + 1) to n
                    dp[i][j][k] = (dp[i][j][k] + dp[i-1][j][k-1] * max(0, n - j)) % MOD

    # Sum up all the ways with total m people
    result = 0
    for j in range(m + 1):
        k = m - j
        if k >= 0:
            result = (result + dp[m][j][k]) % MOD

    return result

